const http = this.helpers.httpRequest;

// ⚙️ CONFIG

// 2. Send to all subscribers
async function sendMsg(phone, text) {
  return http({
    method: 'POST',
    url: 'http://148.230.90.171:8096/message/sendText/wasapea-7c7a2c6c',
    headers: { 'apikey': 'wasapea-evo-key-2026', 'Content-Type': 'application/json' },
    body: { number: phone, text: text }
  });
}



// 📱 SUBSCRIBERS — Add phone numbers (57 + number, no +)
const subscribers = [
  { phone: '573106055920', plan: 'free' },
  // { phone: '573001234567', plan: 'pro' },
];


// 1. Fetch SECOP contracts from datos.gov.co (free, no key)
const base = 'https://www.datos.gov.co/resource/jbjy-vk9h.json';

const now = new Date();
const since = new Date(now.getTime() - 48 * 60 * 60 * 1000).toISOString().split('T')[0];
const until = now.toISOString().split('T')[0];

const params = '$select=nombre_entidad,descripcion_del_proceso,valor_del_contrato,fecha_de_firma,departamento,ciudad,modalidad_de_contratacion,tipo_de_contrato,urlproceso,id_contrato&$where=fecha_de_firma%20%3E=%20%27' + since + '%27&$order=fecha_de_firma%20DESC&$limit=10';
const data = await http({ method: 'GET', url: base + '?' + params });

if (!Array.isArray(data)) throw new Error('SECOP API failed');

// Keywords filter — customize per client
const KEYWORDS = ['eléctric', 'electric', 'energ', 'solar', 'panel', 'transformador', 'red', 'subestación', 'iluminación', 'led', 'cable', 'generador'];

const filtered = data.filter(item => {
  const text = (item.descripcion_del_proceso || '') + ' ' + (item.nombre_entidad || '');
  return KEYWORDS.some(kw => text.toLowerCase().includes(kw.toLowerCase()));
});

if (filtered.length === 0) return { sent: 0, message: 'No matching contracts in last 48h' };

// Format and send each contract
const results = [];
for (const item of filtered) {
  const desc = (item.descripcion_del_proceso || 'Sin descripción').substring(0, 120);
  const valorFmt = item.valor_del_contrato
    ? '$' + Number(item.valor_del_contrato).toLocaleString('es-CO')
    : 'No especificado';
  const fecha = item.fecha_de_firma
    ? new Date(item.fecha_de_firma).toLocaleDateString('es-CO')
    : 'Sin fecha';
  const urlLink = (item.urlproceso && item.urlproceso.url)
    ? item.urlproceso.url
    : 'https://community.secop.gov.co/';

  const text = '📋 *Licitación SECOP*\n\n' +
    '🏛️ *' + item.nombre_entidad + '*\n' +
    '📍 ' + (item.departamento || '') + ', ' + (item.ciudad || '') + '\n' +
    '📝 ' + desc + '...\n' +
    '💰 ' + valorFmt + '\n' +
    '📅 ' + fecha + '\n' +
    '🏷️ ' + (item.modalidad_de_contratacion || '') + '\n\n' +
    '🔗 ' + urlLink + '\n\n' +
    '⚡ *SECOP Alertas*';

  for (const sub of subscribers) {
    try {
      await sendMsg(sub.phone, text);
      results.push({ phone: sub.phone, contract: item.id_contrato, status: 'sent' });
    } catch (e) {
      results.push({ phone: sub.phone, contract: item.id_contrato, status: 'error' });
    }
  }
}

return { sent: results.filter(r => r.status === 'sent').length, contracts: filtered.length, results };
